# Cargar productos
added = 0
for p in products:
    db.upsert_product({
        "brand": p["brand"],
        "reference": p["reference"],
        "name": p["name"],
        "sell_price": p["sell_price"],
        "line": p.get("line", ""),
        "gender": p.get("gender", ""),
        "url": f"https://www.casajoia.com.py/product-page/{p['reference'].lower()}",
        "image_urls": p.get("images", []),
    })
    added += 1

print(f"Cargados {added} productos de Casa Joia")

# Verificar total
with db.get_conn() as conn:
    total = conn.execute("SELECT COUNT(*) FROM products WHERE status='active'").fetchone()[0]
    print(f"Total en catalogo: {total}")
